titulo("PASO 4: Verificaciones de la carga");
print("Conteo total de documentos: " + coleccion.countDocuments());
print("_id unicos: " + coleccion.distinct("_id").length);
print("Combinaciones celda-anio-mes unicas: " +
      coleccion.aggregate([
        { $group: { _id: { c: "$celda.cell_index", a: "$periodo.anio", m: "$periodo.mes" } } },
        { $count: "total" }
      ]).toArray()[0].total);
print("Documentos con 'periodo.fecha_inicio' tipo date: " +
      coleccion.countDocuments({ "periodo.fecha_inicio": { $type: "date" } }));
print("Documentos con 'metricas' tipo object (anidado): " +
      coleccion.countDocuments({ metricas: { $type: "object" } }));
print("Documentos con 'evidencias' tipo array: " +
      coleccion.countDocuments({ evidencias: { $type: "array" } }));
print("Documentos con 'metadatos.datos_simulados' tipo bool: " +
      coleccion.countDocuments({ "metadatos.datos_simulados": { $type: "bool" } }));
print("Documentos CON evidencia de fuego (categoria 'todas'): " +
      coleccion.countDocuments({ evidencias: { $elemMatch: { categoria: "todas", evidencia_fuego: true } } }));
print("Documentos SIN evidencia de fuego (categoria 'todas'): " +
      coleccion.countDocuments({ evidencias: { $elemMatch: { categoria: "todas", evidencia_fuego: false } } }));
print("Documentos con evidencia nominal/alta: " +
      coleccion.countDocuments({ evidencias: { $elemMatch: { categoria: "nominal_alta", evidencia_fuego: true } } }));
titulo("Documento de ejemplo completo (JSON/BSON)");
printjson(coleccion.findOne({ _id: "VCM_0001" }));

// ------------------------------------------------------------
// PASO 5: Las 10 consultas exigidas por la guia (Parte C)
// Cada consulta indica su pregunta en el titulo(); el codigo y el
// resultado quedan documentados tambien en 04_consultas/ e
// interpretados en 05_resultados/ y en el informe PDF.
// ------------------------------------------------------------

titulo("CONSULTA 1: Registros con FRP maxima superior a 20 MW");
coleccion.find(
  { "metricas.frp.maxima_media_mw": { $gt: 20 } },
  { _id: 1, "celda.cell_index": 1, "periodo.anio_mes": 1,
    "metricas.frp.maxima_media_mw": 1 }
).sort({ "metricas.frp.maxima_media_mw": -1, _id: 1 }).forEach(printjson);

titulo("CONSULTA 2: Registros 2023-2024 con evidencia nominal/alta y FRP >= 10 MW");
coleccion.find(
  {
    "periodo.anio": { $in: [2023, 2024] },
    "metricas.frp.maxima_media_mw": { $gte: 10 },
    evidencias: { $elemMatch: { categoria: "nominal_alta", evidencia_fuego: true } }
  },
  { _id: 1, "periodo.anio_mes": 1, "celda.cell_index": 1,
    "metricas.frp.maxima_media_mw": 1 }
).sort({ "periodo.fecha_inicio": 1, _id: 1 }).forEach(printjson);

titulo("CONSULTA 3: Proyeccion de campos esenciales (10 registros con fuego)");
coleccion.find(
  { "metricas.frp.suma_observada_media_mw": { $gt: 0 } },
  { _id: 1, "celda.cell_index": 1, "periodo.anio_mes": 1,
    "metricas.detecciones.media_todas": 1,
    "metricas.frp.suma_observada_media_mw": 1,
    "fuente_satelital.fuente_primaria": 1 }
).sort({ "periodo.fecha_inicio": 1, _id: 1 }).limit(10).forEach(printjson);

titulo("CONSULTA 4: Orden y limite - cinco registros con mayor FRP maxima");
coleccion.find(
  {},
  { _id: 1, "celda.cell_index": 1, "periodo.anio_mes": 1,
    "metricas.frp.maxima_media_mw": 1 }
).sort({ "metricas.frp.maxima_media_mw": -1, _id: 1 }).limit(5).forEach(printjson);

titulo("CONSULTA 5: Campos anidados - disponibilidad 100% y detecciones >= 1");
coleccion.find(
  {
    "calidad_observacion.disponibilidad_pct": 100,
    "metricas.detecciones.media_todas": { $gte: 1 }
  },
  { _id: 1, "periodo.anio_mes": 1, "celda.cell_index": 1,
    "calidad_observacion.disponibilidad_pct": 1,
    "calidad_observacion.dias_validos_media": 1,
    "metricas.detecciones.media_todas": 1 }
).sort({ "metricas.detecciones.media_todas": -1, _id: 1 }).limit(10).forEach(printjson);

titulo("CONSULTA 6: Arreglos con $elemMatch - evidencia nominal/alta");
coleccion.find(
  { evidencias: { $elemMatch: {
      categoria: "nominal_alta", evidencia_fuego: true, detecciones_media: { $gt: 0 }
  } } },
  { _id: 1, "celda.cell_index": 1, "periodo.anio_mes": 1,
    evidencias: { $elemMatch: { categoria: "nominal_alta" } } }
).sort({ "periodo.fecha_inicio": 1, _id: 1 }).limit(10).forEach(printjson);

titulo("CONSULTA 7: Pipeline $match+$group+$sort - intensidad termica por mes calendario");
coleccion.aggregate([
  { $match: { "metricas.frp.suma_observada_media_mw": { $gt: 0 } } },
  { $group: {
      _id: "$periodo.mes", registros_con_fuego: { $sum: 1 },
      frp_total_muestra_mw: { $sum: "$metricas.frp.suma_observada_media_mw" },
      frp_promedio_mw: { $avg: "$metricas.frp.suma_observada_media_mw" },
      frp_maxima_mw: { $max: "$metricas.frp.maxima_media_mw" }
  } },
  { $project: { _id: 0, mes: "$_id", registros_con_fuego: 1,
      frp_total_muestra_mw: { $round: ["$frp_total_muestra_mw", 2] },
      frp_promedio_mw: { $round: ["$frp_promedio_mw", 2] },
      frp_maxima_mw: { $round: ["$frp_maxima_mw", 2] }
  } },
  { $sort: { frp_total_muestra_mw: -1, mes: 1 } }
]).forEach(printjson);

titulo("CONSULTA 8: Pipeline $match+$group+$sort - variacion anual de metricas de fuego");
coleccion.aggregate([
  { $match: { "metricas.frp.suma_observada_media_mw": { $gt: 0 } } },
  { $group: {
      _id: "$periodo.anio", registros_con_fuego: { $sum: 1 },
      detecciones_promedio: { $avg: "$metricas.detecciones.media_todas" },
      frp_promedio_mw: { $avg: "$metricas.frp.suma_observada_media_mw" },
      frp_total_muestra_mw: { $sum: "$metricas.frp.suma_observada_media_mw" },
      frp_maxima_mw: { $max: "$metricas.frp.maxima_media_mw" }
  } },
  { $project: { _id: 0, anio: "$_id", registros_con_fuego: 1,
      detecciones_promedio: { $round: ["$detecciones_promedio", 3] },
      frp_promedio_mw: { $round: ["$frp_promedio_mw", 2] },
      frp_total_muestra_mw: { $round: ["$frp_total_muestra_mw", 2] },
      frp_maxima_mw: { $round: ["$frp_maxima_mw", 2] }
  } },
  { $sort: { frp_total_muestra_mw: -1, anio: 1 } }
]).forEach(printjson);

titulo("CONSULTA 9: $unwind+$group - evidencia total vs. nominal/alta");
coleccion.aggregate([
  { $unwind: "$evidencias" },
  { $group: {
      _id: "$evidencias.categoria", documentos_evaluados: { $sum: 1 },
      documentos_con_fuego: { $sum: { $cond: ["$evidencias.evidencia_fuego", 1, 0] } },
      detecciones_promedio: { $avg: "$evidencias.detecciones_media" },
      presencia_promedio: { $avg: "$evidencias.presencia_fraccion" }
  } },
  { $project: { _id: 0, categoria: "$_id", documentos_evaluados: 1,
      documentos_con_fuego: 1,
      detecciones_promedio: { $round: ["$detecciones_promedio", 3] },
      presencia_promedio: { $round: ["$presencia_promedio", 3] }
  } },
  { $sort: { categoria: 1 } }
]).forEach(printjson);

titulo("CONSULTA 10: Integradora - dataset plano celda-mes para analisis estadistico/ML");
coleccion.aggregate([
  { $match: {
      "metricas.frp.suma_observada_media_mw": { $gt: 0 },
      "calidad_observacion.disponibilidad_pct": { $gte: 95 }
  } },
  { $set: {
      frp_por_deteccion_mw: { $cond: [
        { $gt: ["$metricas.detecciones.media_todas", 0] },
        { $divide: ["$metricas.frp.suma_observada_media_mw",
                    "$metricas.detecciones.media_todas"] }, 0
      ] },
      proporcion_nominal_alta: { $cond: [
        { $gt: ["$metricas.detecciones.media_todas", 0] },
        { $divide: ["$metricas.detecciones.media_nominal_alta",
                    "$metricas.detecciones.media_todas"] }, 0
      ] }
  } },
  { $project: {
      _id: 0, registro_id: "$_id", cell_index: "$celda.cell_index",
      anio: "$periodo.anio", mes: "$periodo.mes", anio_mes: "$periodo.anio_mes",
      detecciones_media: { $round: ["$metricas.detecciones.media_todas", 3] },
      frp_total_media_mw: { $round: ["$metricas.frp.suma_observada_media_mw", 2] },
      frp_maxima_mw: { $round: ["$metricas.frp.maxima_media_mw", 2] },
      frp_por_deteccion_mw: { $round: ["$frp_por_deteccion_mw", 2] },
      proporcion_nominal_alta: { $round: ["$proporcion_nominal_alta", 3] },
      disponibilidad_pct: "$calidad_observacion.disponibilidad_pct",
      presencia_fuego: { $literal: 1 }
  } },
  { $sort: { frp_total_media_mw: -1, registro_id: 1 } },
  { $limit: 15 }
]).forEach(printjson);

// ------------------------------------------------------------
// PASO 6: Operaciones de actualizacion (Parte D)
// IMPORTANTE: las tres actualizaciones agregan o modifican
// UNICAMENTE metadatos operativos del laboratorio (bandera de
// revision, estado de revision, bitacora de procesamiento).
// Ningun valor satelital real (FRP, detecciones, presencia,
// calidad de observacion) se modifica.
// ------------------------------------------------------------

titulo("ACTUALIZACION 1: campo simple con updateOne() (revisado_manualmente)");
const documentoFrpMaxima = coleccion.find(
  {}, { _id: 1, "metricas.frp.maxima_media_mw": 1 }
).sort({ "metricas.frp.maxima_media_mw": -1, _id: 1 }).limit(1).toArray()[0];
print("Documento seleccionado (mayor FRP maxima de la muestra): " + documentoFrpMaxima._id);
print("ANTES:");
printjson(coleccion.findOne({ _id: documentoFrpMaxima._id }, { _id: 1, revisado_manualmente: 1 }));
const resultadoActualizacion1 = coleccion.updateOne(
  { _id: documentoFrpMaxima._id },
  { $set: { revisado_manualmente: true } }
);
print("Resultado updateOne -> matched: " + resultadoActualizacion1.matchedCount +
      ", modified: " + resultadoActualizacion1.modifiedCount);
print("DESPUES:");
printjson(coleccion.findOne({ _id: documentoFrpMaxima._id }, { _id: 1, revisado_manualmente: 1 }));
print("Efecto: agrega el metadato operativo booleano 'revisado_manualmente' a un unico " +
      "documento (el de mayor FRP de la muestra); no altera ningun valor satelital.");

titulo("ACTUALIZACION 2: campo anidado con updateMany() (metadatos.estado_revision)");
print("ANTES (3 documentos con evidencia de fuego, ordenados por _id):");
coleccion.find(
  { evidencias: { $elemMatch: { categoria: "todas", evidencia_fuego: true } } },
  { _id: 1, "metadatos.estado_revision": 1 }
).sort({ _id: 1 }).limit(3).forEach(printjson);
const resultadoActualizacion2 = coleccion.updateMany(
  { evidencias: { $elemMatch: { categoria: "todas", evidencia_fuego: true } } },
  { $set: { "metadatos.estado_revision": "revisado_taller_nosql" } }
);
print("Resultado updateMany -> matched: " + resultadoActualizacion2.matchedCount +
      ", modified: " + resultadoActualizacion2.modifiedCount);
print("DESPUES (mismos 3 documentos):");
coleccion.find(
  { evidencias: { $elemMatch: { categoria: "todas", evidencia_fuego: true } } },
  { _id: 1, "metadatos.estado_revision": 1 }
).sort({ _id: 1 }).limit(3).forEach(printjson);
print("Efecto: agrega el campo anidado 'metadatos.estado_revision' (metadato operativo) " +
      "a los 70 documentos con evidencia de fuego; los valores satelitales no cambian.");

titulo("ACTUALIZACION 3: incorporacion de informacion nueva con $push (bitacora_laboratorio)");
print("ANTES (un documento de referencia):");
printjson(coleccion.findOne({ _id: "VCM_0001" }, { _id: 1, bitacora_laboratorio: 1 }));
const fechaProcesamiento = new Date();
const resultadoActualizacion3 = coleccion.updateMany(
  {},
  { $push: { bitacora_laboratorio: {
      accion: "carga_taller_nosql_fireforest",
      responsable: "Grupo04",
      fecha_procesamiento: fechaProcesamiento
  } } }
);
print("Resultado updateMany -> matched: " + resultadoActualizacion3.matchedCount +
      ", modified: " + resultadoActualizacion3.modifiedCount);
print("DESPUES (mismo documento de referencia):");
printjson(coleccion.findOne({ _id: "VCM_0001" }, { _id: 1, bitacora_laboratorio: 1 }));
print("Efecto: incorpora en los 105 documentos un nuevo arreglo de metadatos operativos " +
      "'bitacora_laboratorio' mediante $push, sin modificar los campos satelitales originales.");

titulo("FIN DEL SCRIPT - taller_nosql_fireforest.evidencia_viirs_celda_mes");
